[8986]={["aftermath"]="Bodley imbued the brazier and directed Mor's summons to Voone's chamber in Tazz'Alaor. The fragment had to be taken before his old comrade could rest.",["atomIDs"]={"8986:description:1-19","8986:description:21-239","8986:description:244-377","8986:description:379-507","8986:objective:1-78"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"8986:completion:1-20","8986:completion:22-78","8986:completion:83-305","8986:completion:307-362","8986:completion:367-481","8986:completion:483-497"},["minimumStage"]=2,["objectiveSummary"]="Recover druidical remains from the silithid near Hive'Regal for Bodley.",["opening"]="Mor Grayhoof had friends in the Cenarion Circle who had fallen to Silithus's insects. Their remains would furnish a personal focus strong enough to draw his corrupted spirit to Bodley's brazier.",["pending"]="{actor} would recover the remains from the silithid around Hive'Regal.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} returned the druidical remains to Bodley.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="028b96eca2c087a0e89458d049565c880b1e34729783a569d0e97c8810418cc5",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
[8987]={["aftermath"]="Bodley imbued the brazier for a summons at the Crimson Throne in Stratholme, where the siblings' souls had been twisted by the amulet.",["atomIDs"]={"8987:description:1-19","8987:description:21-241","8987:description:246-327","8987:description:329-385","8987:description:387-496","8987:objective:1-89"},["coverageQualification"]="INDIVIDUALLY_AUTHORED_RETAINED_SOURCE_ACCOUNT",["endingAtomIDs"]={"8987:completion:1-20","8987:completion:22-76","8987:completion:81-265","8987:completion:267-374","8987:completion:379-493","8987:completion:495-509"},["minimumStage"]=2,["objectiveSummary"]="Recover a brilliant zealot's sword from Tyr's Hand for Bodley.",["opening"]="Jarien and Sothos had aspired to knighthood in the Scarlet Crusade. A praetorian's sword from Tyr's Hand would furnish a focus tied to that ambition, allowing the brazier to call the siblings' remains.",["pending"]="{actor} would seek the sword among Tyr's Hand's praetorians.",["referenceStatus"]="UNVERIFIED_CLIENT_REFERENCE",["result"]="{actor} brought the sword to Bodley.",["reviewStatus"]="AUTHOR_SOURCE_READ_NOT_INDEPENDENTLY_CERTIFIED",["sourceHash"]="febea94d95404acd48439e667cac6324557e61db5cbcc05a0fc0dcdf5b0684a2",["sourceURL"]="https://www.curseforge.com/wow/addons/questdb/files/9014639",["unresolvedFields"]={"currentServerPlayability"}},
